import{c as a,Q as s,j as e,m as n}from"./chunks/framework.DOi4mjdC.js";const l="/assets/zh-cn_formulaimage_0000002339181076.xMLkZfnq.png",d="/assets/zh-cn_formulaimage_0000002339021404.BNOynhmv.png",A=JSON.parse('{"title":"MulsCast(ISASI)","description":"","frontmatter":{},"headers":[{"level":1,"title":"MulsCast\\\\(ISASI\\\\)","slug":"mulscastisasi"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Memory矢量计算/复合计算/MulsCast(ISASI).md","filePath":"api/SIMD-API/基础API/Memory矢量计算/复合计算/MulsCast(ISASI).md"}'),r={name:"api/SIMD-API/基础API/Memory矢量计算/复合计算/MulsCast(ISASI).md"};function o(i,t,c,p,h,u){return s(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="mulscast-isasi" tabindex="-1">MulsCast(ISASI) <a class="header-anchor" href="#mulscast-isasi" aria-label="Permalink to &quot;MulsCast\\(ISASI\\)&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>x</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>将矢量源操作数前count个数据与标量相乘再按照CAST_ROUND模式转换成half类型， 并将计算结果写入dst，此接口支持标量在前和标量在后两种场景。计算公式如下。</p><p><img src="'+l+'" alt=""></p><p>其中标量输入也支持配置LocalTensor单点元素，计算公式如下，idx表示LocalTensor单点元素的位置系数。</p><p><img src="'+d+`" alt=""></p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T0 = BinaryDefaultType, typename T1 = BinaryDefaultType, const BinaryConfig &amp;config = DEFAULT_BINARY_CONFIG, typename T2, typename T3, typename T4&gt;</span></span>
<span class="line"><span>__aicore__ inline void MulsCast(const T2 &amp;dst, const T3 &amp;src0, const T4 &amp;src1, const uint32_t count)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T0</td><td>目的操作数数据类型。 预留参数，暂未启用，为后续的功能扩展做保留，需要指定时，传入默认值BinaryDefaultType即可。</td></tr><tr><td>T1</td><td>源操作数数据类型。 预留参数，暂未启用，为后续的功能扩展做保留，需要指定时，传入默认值BinaryDefaultType即可。</td></tr><tr><td>config</td><td>类型为BinaryConfig，当标量为LocalTensor单点元素类型时生效，用于指定单点元素操作数位置。默认值DEFAULT_BINARY_CONFIG，表示右操作数为标量。 &lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot; id=&quot;screen420895553620&quot;&gt;struct BinaryConfig { int8_t scalarTensorIndex = 1; // 用于指定标量为LocalTensor单点元素时标量的位置，0表示左操作数，1表示右操作数 }; constexpr BinaryConfig DEFAULT_BINARY_CONFIG = {1};&lt;/pre&gt;</td></tr><tr><td>T2</td><td>LocalTensor类型，根据输入参数dst自动推导相应的数据类型，开发者无需配置该参数，保证dst满足数据类型的约束即可。</td></tr><tr><td>T3</td><td>LocalTensor类型或标量类型，根据输入参数src0自动推导相应的数据类型，开发者无需配置该参数，保证src0满足数据类型的约束即可。</td></tr><tr><td>T4</td><td>LocalTensor类型或标量类型，根据输入参数src1自动推导相应的数据类型，开发者无需配置该参数，保证src1满足数据类型的约束即可。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 LocalTensor的起始地址需要32字节对齐。 Ascend 950PR/Ascend 950DT，支持的数据类型为：half 不同数据类型对应的精度转换规则见表3。</td></tr><tr><td>src0/src1</td><td>输入</td><td>源操作数。 类型为LocalTensor时，支持当作矢量操作数或标量单点元素，支持的TPosition为VECIN/VECCALC/VECOUT。 LocalTensor的起始地址需要32字节对齐。 Ascend 950PR/Ascend 950DT，支持的数据类型为：float 类型为标量时： Ascend 950PR/Ascend 950DT，支持的数据类型为：float</td></tr><tr><td>count</td><td>输入</td><td>参与计算的元素个数。</td></tr></tbody></table><p><strong>表 3</strong> 精度转换规则</p><table tabindex="0"><thead><tr><th>src类型</th><th>dst类型</th><th>类型转换模式介绍</th></tr></thead><tbody><tr><td>float</td><td>half</td><td>将源操作数按照CAST_ROUND模式取到half所能表示的数，以half格式（溢出默认按照饱和处理）存入dst中。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>左操作数及右操作数中，必须有一个为矢量；当前不支持左右操作数同时为标量。</li><li>本接口传入LocalTensor单点数据作为标量时，idx参数需要传入编译期已知的常量，传入变量时需要声明为constexpr。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 标量在后示例</span></span>
<span class="line"><span>AscendC::MulsCast(dstLocal, src0Local, src1Local[0], 512);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 标量在前示例</span></span>
<span class="line"><span>static constexpr AscendC::BinaryConfig config = { 0 };</span></span>
<span class="line"><span>AscendC::MulsCast&lt;BinaryDefaultType, BinaryDefaultType, config&gt;(dstLocal, src0Local[0], src1Local, 512);</span></span></code></pre></div><p>结果示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入数据src0Local：[6 5 11 ... ]</span></span>
<span class="line"><span>输入数据src1Local：2</span></span>
<span class="line"><span>输出数据dstLocal：[12 10 22 ... ]</span></span></code></pre></div>`,25)])])}const b=a(r,[["render",o]]);export{A as __pageData,b as default};
